const input = $input.first().json;
let payload = input.output ?? input.text ?? input;

if (typeof payload === 'string') {
  try {
    const match = payload.match(/```(?:json)?\s*\n?([\s\S]*?)\n?\s*```/);
    let cleanJson = match ? match[1].trim() : payload.trim();
    const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      cleanJson = jsonMatch[0];
    }
    payload = JSON.parse(cleanJson);
  } catch (error) {
    payload = {};
  }
}

function canonicalFormat(value) {
  const normalized = String(value ?? '').trim().toLocaleLowerCase('tr-TR');

  if (!normalized || normalized === 'auto' || normalized === 'otomatik seç') {
    return undefined;
  }

  if (normalized === 'banner' || normalized === 'web banner') return 'Banner';
  if (normalized === 'story' || normalized === 'hikaye') return 'Story';
  if (normalized === 'meta post' || normalized === 'metapost' || normalized === 'post') {
    return 'Meta Post';
  }

  return null;
}

const requestedFormat = $('Claim_Attempt').first().json.data.format;
const explicitFormat = canonicalFormat(requestedFormat);

const llmIntent = ['Meta Post', 'Story', 'Banner'].includes(payload.intent)
  ? payload.intent
  : null;

// Öncelik: kullanıcı formatı > LLM kararı > Meta Post varsayılanı
const intent = explicitFormat === null
  ? 'Meta Post'
  : explicitFormat || llmIntent || 'Meta Post';

const details = payload.visual_details ?? {};
const prices = details.prices ?? {};
const campaign = details.campaign ?? {};

function defaultWidth(intentValue, value) {
  const parsed = Number.parseInt(value, 10);
  if (intentValue === 'Meta Post') return 1080;
  if (intentValue === 'Story') return 1080;
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 1600;
}

function defaultHeight(intentValue, value) {
  const parsed = Number.parseInt(value, 10);
  if (intentValue === 'Meta Post') return 1350;
  if (intentValue === 'Story') return 1920;
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 600;
}

// Orijinal yapılandırılmış veri modeli (Database & Dashboard uyumluluğu için)
const structuredOutput = {
  intent,
  visual_details: {
    product_name: String(details.product_name ?? '').trim(),
    category: String(details.category ?? '').trim(),
    slogan: String(details.slogan ?? '').trim(),
    image_url: '',
    width: defaultWidth(intent, details.width),
    height: defaultHeight(intent, details.height),
    prices: {
      old_price: String(prices.old_price ?? '').trim(),
      new_price: String(prices.new_price ?? '').trim(),
      discount_rate: String(prices.discount_rate ?? '').trim(),
    },
    campaign: {
      campaign_name: String(campaign.campaign_name ?? '').trim(),
      campaign_code: String(campaign.campaign_code ?? '').trim(),
    }
  }
};

// Parent workflow bağlamındaki diğer düğümlerden verileri çekiyoruz
const prompts = $('Claim_Attempt').first().json.data.prompts;
const brand = $('Claim_Attempt').first().json.data.brand;
const briefText = $('Claim_Attempt').first().json.data.briefText;

const normalized = {
  // Alt akışlar için doğrudan düzleştirilmiş alanlar
  product_name: structuredOutput.visual_details.product_name,
  category: structuredOutput.visual_details.category,
  slogan: structuredOutput.visual_details.slogan,
  source_image_path: String(
  $('Claim_Attempt').first().json.data.imageId || ''
).trim(),
  width: structuredOutput.visual_details.width,
  height: structuredOutput.visual_details.height,
  old_price: structuredOutput.visual_details.prices.old_price,
  new_price: structuredOutput.visual_details.prices.new_price,
  discount_rate: structuredOutput.visual_details.prices.discount_rate,
  campaign_name: structuredOutput.visual_details.campaign.campaign_name,
  campaign_code: structuredOutput.visual_details.campaign.campaign_code,
  prompts,
  brand,
  briefText,
  raw_llm_output: input,

  // Veritabanına (brief_json) kaydedilecek yapılandırılmış çıktı
  output: structuredOutput
};

return [
  {
    json: normalized
  }
];

const executionData = $input.first().json;
const errorMsg = executionData.data?.resultData?.error?.message || executionData.data?.resultData?.error?.description || "Bilinmeyen Hata";
let jobId = "";

try {
  // n8n API yanıtından Brief_Tetikleyici düğümünün body.jobId alanını çekeriz
  const runData = executionData.data.resultData.runData;
  const webhookData = runData.Brief_Tetikleyici[0].data.main[0][0].json;
  jobId = webhookData.body.jobId;
} catch (e) {
  jobId = "";
}

// jobId'nin geçerli bir UUID olup olmadığını doğrula
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const isValidUuid = jobId && uuidRegex.test(jobId);

// Geçerli bir jobId yoksa, Supabase'e yazılacak bir iş kaydı olmadığından boş dizi dönerek akışı durdur
if (!isValidUuid) {
  return [];
}

return [{
  json: {
    jobId: jobId,
    error: errorMsg
  }
}];

const crypto = require('crypto');

const items = $input.all();
if (!items || items.length === 0) return [];

const headers = items[0].json.headers || {};
const body = items[0].json.body || {};

const signature = headers['x-vitrinos-signature'];
const timestamp = headers['x-vitrinos-timestamp'];
const secret = $env.N8N_API_SALT || $env.HMAC_SECRET; // n8n sunucusunda N8N_API_SALT veya HMAC_SECRET tanımlı olmalıdır

if (!secret) {
  throw new Error("Sunucu Yapılandırma Hatası: N8N_API_SALT veya HMAC_SECRET tanımlı değil.");
}

if (!signature || !timestamp) {
  throw new Error("Yetkilendirme Hatası: İmza veya zaman damgası eksik.");
}

// Replay saldırısı koruması: 5 dakika (300.000 ms) zaman toleransı
const now = Date.now();
const requestTime = parseInt(timestamp, 10);
if (isNaN(requestTime) || Math.abs(now - requestTime) > 300000) {
  throw new Error("Yetkilendirme Hatası: İstek zaman aşımına uğradı (Replay Attack önlendi).");
}

// Payload doğrulaması
const payloadString = JSON.stringify(body);
const dataToVerify = `${timestamp}.${payloadString}`;

const expectedSignature = crypto
  .createHmac('sha256', secret)
  .update(dataToVerify)
  .digest('hex');

if (signature !== expectedSignature) {
  throw new Error("Yetkilendirme Hatası: Geçersiz imza. İstek manipüle edilmiş olabilir.");
}

return items;

